                    self._send_json(200, {"key": key, "value": value})
                else:
                    self._error(404, "key not found")
            elif self.command == "PUT":
                self._put(key)
            elif self.command == "DELETE":
                if self.server.store.delete(key):
                    self.send_response(204)
                    self.send_header("Content-Length", "0")
                    self.end_headers()
                else:
                    self._error(404, "key not found")
            else:
                self._method_not_allowed("GET, PUT, DELETE")
            return
        self._error(404, "route not found")

    def _method_not_allowed(self, allowed: str) -> None:
        body = json.dumps({"error": "method not allowed"}, separators=(",", ":")).encode("utf-8")
        self.send_response(405)
        self.send_header("Allow", allowed)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(body)

    def _put(self, key: str) -> None:
        payload = self._read_json()
        if not isinstance(payload, dict) or "value" not in payload or not set(payload).issubset({"value", "ttl_seconds"}):
            raise RequestError(400, "body must be an object containing value and optional ttl_seconds")
        ttl = payload.get("ttl_seconds")
        if ttl is not None and (
            isinstance(ttl, bool)
            or not isinstance(ttl, (int, float))
            or not math.isfinite(ttl)
            or ttl <= 0
        ):
            raise RequestError(400, "ttl_seconds must be a finite number greater than zero")
        replaced = self.server.store.put(key, payload["value"], ttl)
        self._send_json(200 if replaced else 201, {"key": key, "value": payload["value"]})

    def _handle(self) -> None:
        try:
            self._dispatch()
        except RequestError as exc:
            self._error(exc.status, exc.message)
        except StoreError as exc:
            print(str(exc), file=sys.stderr)
            self._error(500, "persistent storage error")
        except (BrokenPipeError, ConnectionResetError):
            pass

    do_GET = _handle
    do_PUT = _handle
    do_DELETE = _handle
    do_POST = _handle
    do_PATCH = _handle
    do_HEAD = _handle
    do_OPTIONS = _handle


class RequestError(Exception):
    def __init__(self, status: int, message: str) -> None:
        super().__init__(message)
        self.status = status
        self.message = message


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Persistent HTTP key-value service")
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", type=int, required=True)
    parser.add_argument("--data", type=Path, required=True)
    args = parser.parse_args()
    if not 0 <= args.port <= 65535:
        parser.error("--port must be between 0 and 65535")
    return args


def main() -> int:
    args = parse_args()
    try:
        store = Store(args.data)
        server = Server((args.host, args.port), store)
    except (OSError, StoreError) as exc:
        print(f"startup failed: {exc}", file=sys.stderr)
        return 1

    stopping = threading.Event()

    def stop(signum: int, frame: Any) -> None:
        del signum, frame
        if not stopping.is_set():
            stopping.set()
            threading.Thread(target=server.shutdown, daemon=True).start()

    signal.signal(signal.SIGTERM, stop)
    signal.signal(signal.SIGINT, stop)
    print(f"LISTENING {server.server_address[1]}", flush=True)
    try:
        server.serve_forever()
    finally:
        server.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
# Persistent HTTP key-value service

A dependency-free Python 3.11+ HTTP service with JSON-file persistence, optional
per-key TTLs, atomic disk updates, and concurrent request handling.

## Run

```sh
python3 server.py --host 127.0.0.1 --port 8080 --data ./data.json
```

Using `--port 0` selects a free port; the service prints `LISTENING <port>` as
its first stdout line. Diagnostics go to stderr. Send `SIGTERM` or press Ctrl-C
for a clean shutdown.

## API

```sh
curl -X PUT http://127.0.0.1:8080/v1/kv/example \
  -H 'Content-Type: application/json' \
  -d '{"value":{"answer":42},"ttl_seconds":60}'
curl http://127.0.0.1:8080/v1/kv/example
curl http://127.0.0.1:8080/v1/keys
curl -X DELETE http://127.0.0.1:8080/v1/kv/example
curl http://127.0.0.1:8080/health
```

Keys are URL-encoded UTF-8 strings. They may contain spaces but cannot be empty
or contain `/`. Request bodies are limited to 1 MiB. Every response other than
a successful `DELETE` (HTTP 204) is JSON.
